(function(){'use strict';const button=document.querySelector('.tour-toggle-days');if(!button)return;const days=[...document.querySelectorAll('.tour-day')];function sync(){button.textContent=days.every(d=>d.open)?'Collapse all days −':'Expand all days +';}button.addEventListener('click',()=>{const open=!days.every(d=>d.open);days.forEach(day=>day.open=open);sync();});days.forEach(day=>day.addEventListener('toggle',sync));sync();})();
